import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.DtFQgA2F.js";const b="/CG/assets/vector-matrix.D9ftWhsG.svg",p=JSON.parse('{"title":"向量与矩阵","description":"","frontmatter":{"title":"向量与矩阵"},"headers":[],"relativePath":"notes/02-math/vector-matrix.md","filePath":"notes/02-math/vector-matrix.md","lastUpdated":1794984217000}'),o={name:"notes/02-math/vector-matrix.md"};function h(i,t,l,s,n,x){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="向量与矩阵" tabindex="-1">向量与矩阵 <a class="header-anchor" href="#向量与矩阵" aria-label="Permalink to &quot;向量与矩阵&quot;">​</a></h1><p><img src="'+b+'" alt="向量与矩阵"></p><h2 id="图文要点" tabindex="-1">图文要点 <a class="header-anchor" href="#图文要点" aria-label="Permalink to &quot;图文要点&quot;">​</a></h2><h3 id="_1-向量写法" tabindex="-1">① 向量写法 <a class="header-anchor" href="#_1-向量写法" aria-label="Permalink to &quot;① 向量写法&quot;">​</a></h3><p>|v| = √(3² + 4²) = 5 · 矩阵写法（高级）：把向量看作 1×3 / 3×1 矩阵，方便与变换矩阵运算 行向量（1×3 矩阵）<br>v = [ x y z ]<br>横着写：1 行 3 列</p><p>v = (3, 4, 0) 列向量（3×1 矩阵）★ 推荐<br> [ x ]<br>v = [ y ]<br> [ z ]<br>竖着写：3 行 1 列</p><p>转置（Transpose）<br>vᵀ：行 ↔ 列互换<br>[ x y z ]ᵀ = 列向量形式</p><p>为什么推荐列向量：变换矩阵左乘列向量 M·v，与矩阵乘法顺序天然一致；<br>行向量则写作 vᵀ·Mᵀ（矩阵转置换边）</p><p>z（朝屏幕外）<br>坐标写法（基础）：v = (x, y, z) —— 用 3 个分量表示，最直观（图例 v = (3, 4, 0)）</p><h3 id="_2-向量运算-基础六则" tabindex="-1">② 向量运算（基础六则） <a class="header-anchor" href="#_2-向量运算-基础六则" aria-label="Permalink to &quot;② 向量运算（基础六则）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>加法</th><th>减法</th><th>数乘</th></tr></thead><tbody><tr><td>a + b = (ax+bx, ay+by, az+bz)</td><td>a − b = (ax−bx, ay−by, az−bz)</td><td>k·a = (k·ax, k·ay, k·az)</td></tr><tr><td>对应分量相加；几何上 = 平行四边形法则</td><td>= a + (−b)；箭头从 b 端指向 a 端</td><td>长度缩放 |k| 倍；k &lt; 0 反向</td></tr><tr><td>取模</td><td>规范化（Normalize）</td><td>点乘（数量积）</td></tr><tr><td>|a| = √(ax² + ay² + az²)</td><td>â = a / |a|</td><td>a·b = ax·bx + ay·by + az·bz</td></tr><tr><td>向量的长度；恒 ≥ 0，零向量模为 0</td><td>单位向量：长度归一化为 1，只保留方向</td><td>= |a||b|cosθ；结果是标量，判夹角/投影/同向</td></tr></tbody></table><h3 id="_3-叉乘-向量积-——-仅-3d-向量" tabindex="-1">③ 叉乘（向量积）—— 仅 3D 向量 <a class="header-anchor" href="#_3-叉乘-向量积-——-仅-3d-向量" aria-label="Permalink to &quot;③ 叉乘（向量积）—— 仅 3D 向量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>a × b 是向量：垂直于 a、b 所在平面</th><th>叉乘计算公式（3×3 行列式展开）：</th></tr></thead><tbody><tr><td>长度 |a×b| = |a||b|sinθ —— 恰好等于 a、b 围成的平行四边形面积</td><td>| i j k |<br>a × b = | ax ay az |<br> | bx by bz |</td></tr></tbody></table><p>如何区分左手系 / 右手系：</p><table tabindex="0"><thead><tr><th>右手系：右手四指从 a 弯向 b（&lt; 180°），拇指指向即 a×b 方向（图形学默认）</th><th>= i·(ay·bz − az·by) − j·(ax·bz − az·bx) + k·(ax·by − ay·bx)</th></tr></thead><tbody><tr><td>左手系：按左手同样动作，a×b 方向相反</td><td>x 分量 = ay·bz − az·by y 分量 = az·bx − ax·bz（带负号） z 分量 = ax·by − ay·bx</td></tr><tr><td>自检口诀：x̂ × ŷ = ẑ（右手系）</td><td>记忆：分量循环『十字相乘相减』；y 分量因行列式展开带 − 号，最容易抄错</td></tr></tbody></table><p>验证：写完后用 (1,0,0)×(0,1,0) = (0,0,1) 自测；任意向量 × 自身 = 零向量</p><h3 id="_4-踩坑记录" tabindex="-1">④ 踩坑记录 <a class="header-anchor" href="#_4-踩坑记录" aria-label="Permalink to &quot;④ 踩坑记录&quot;">​</a></h3><p>· 用 double 不用 float（渲染累积误差出噪点） · 归一化零向量会除零 → NaN：先 near_zero() 判断兜底<br>· 叉乘 y 分量符号最易抄错 → 用 x̂×ŷ=ẑ 自测 · 点乘判断朝向记得先归一化，否则数值无意义</p>',18)])])}const _=a(o,[["render",h]]);export{p as __pageData,_ as default};
